"""Optional lazy import of torch._meta_registrations.

The hook is inert unless XSAI_LAZYMETA is explicitly enabled.  It is kept
small and isolated so the normal eager import and warmd ABI remain unchanged.
"""
import importlib
import importlib.machinery
import importlib.util
import os
import sys
import types

if os.environ.get("XSAI_LAZYMETA", "").lower() in ("1", "true", "yes", "on"):
    name = "torch._meta_registrations"
    class Lazy(types.ModuleType):
        def __init__(self):
            super().__init__(name)
            self._real = None

        def _load(self):
            if self._real is None:
                parent = importlib.import_module("torch")
                spec = importlib.machinery.PathFinder.find_spec(
                    name, getattr(parent, "__path__", None))
                if spec is None or spec.loader is None:
                    raise ImportError("cannot locate " + name)
                real = importlib.util.module_from_spec(spec)
                sys.modules[name] = real
                spec.loader.exec_module(real)
                parent._meta_registrations = real
                self._real = real
            return self._real

        def __getattr__(self, key):
            return getattr(self._load(), key)

        def __dir__(self):
            return dir(self._load())

    sys.modules.setdefault(name, Lazy())
